(function(){
 const KEY='nawaf-hq-v3', $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
 const getState=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}};
 const employees=[{id:'omar',name:'عمر',role:'التقنية والبحث',x:77,y:28},{id:'lian',name:'ليان',role:'المنتج والتجربة',x:21,y:41},{id:'noura',name:'نورة',role:'الجودة والمراجعة',x:31,y:74},{id:'sara',name:'سارة',role:'المدير العام AI',x:69,y:73}];
 const rooms=[{id:'board',label:'مجلس الشركة',x:50,y:15},{id:'analytics',label:'التحليلات',x:86,y:48},{id:'product',label:'المنتج والتجربة',x:16,y:39},{id:'tech',label:'التقنية والبحث',x:83,y:30},{id:'quality',label:'الجودة والمراجعة',x:27,y:72},{id:'general',label:'الإدارة العامة',x:71,y:71}];
 const st=id=>(getState()?.employees||[]).find(e=>e.id===id)||{status:'READY'};
 const statusLabel=v=>({READY:'جاهز',IDLE:'متاح',WORKING:'يعمل',RESEARCHING:'يبحث',COLLABORATING:'يتعاون',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظار نواف'})[v]||v||'جاهز';
 function openPerson(id){if(typeof window.NawafHQ?.employeeView==='function')return window.NawafHQ.employeeView(id);if(id==='sara')window.NawafCompanyBoard?.open?.('company')}
 function build(){const office=$('.office');if(!office||office.dataset.referenceOffice==='1')return;office.dataset.referenceOffice='1';office.classList.add('hq-reference-office');office.innerHTML=`<div class="ref-office-shell"><div class="ref-office-head"><div><span><i></i> LIVE INTERACTIVE OFFICE</span><b>المقر التفاعلي</b><small>مبني على المرجع مباشرة — اضغط على الموظفين والغرف</small></div><button id="ref-board">مجلس الشركة</button></div><div class="ref-stage"><div class="ref-vignette"></div><button class="core-hotspot"><span>NAWAF HQ</span><small>COMMAND CORE</small></button>${rooms.map(r=>`<button class="room-hotspot room-${r.id}" data-room="${r.id}" style="--x:${r.x}%;--y:${r.y}%"><span>${r.label}</span></button>`).join('')}${employees.map(e=>{const s=st(e.id);return `<button class="employee-hotspot state-${String(s.status).toLowerCase()}" data-agent="${e.id}" style="--x:${e.x}%;--y:${e.y}%"><span class="mini-bot"><i class="head"><b></b><b></b></i><i class="body"></i></span><span class="emp-card"><b>${e.name}</b><small>${e.role}</small><em>${statusLabel(s.status)}</em></span></button>`}).join('')}<div class="ref-hint">حرّك المؤشر فوق أي موظف أو قسم</div></div><div class="ref-office-foot"><span>● الحالات مربوطة بالعمل الحقيقي</span><small>REFERENCE INTERACTIVE MODE</small></div></div>`;$('#ref-board',office).onclick=()=>window.NawafCompanyBoard?.open?.('company');$('.core-hotspot',office).onclick=()=>window.NawafCompanyBoard?.open?.('company');$$('[data-agent]',office).forEach(b=>b.onclick=()=>openPerson(b.dataset.agent));$$('[data-room]',office).forEach(b=>b.onclick=()=>{if(b.dataset.room==='board')window.NawafCompanyBoard?.open?.('company')})}
 function boot(){build()}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();new MutationObserver(()=>{const o=$('.office');if(o&&!o.dataset.referenceOffice)setTimeout(boot,80)}).observe(document.documentElement,{childList:true,subtree:true});
})();